typedef float rational_t;
class color
{
public:
	rational_t r, g, b, a;
	color() {}
	color(const color& c) : r(c.r), g(c.g), b(c.b), a(c.a) {}
	color& operator=(const color& c) { r = c.r; g = c.g; b = c.b; a = c.a; return *this; }
};

class IGOWidget
{
protected:
	bool display;
public:
	virtual ~IGOWidget();
	virtual void SetDisplay(const bool d = true);
	virtual void Update(const float dt);
	virtual void Draw(void);
	virtual bool GetDisplay(void) const;
};

class SpecialMeter
{
public:
	bool CanRegionLink(void) const;
};

class PanelQuad
{
public:
	virtual ~PanelQuad();
	virtual void Init(float, float, float, float, float, float, float, float, float, float, float, float, float, int);
	virtual void TurnOn(bool);
	virtual void SetLayer(int);
	virtual void Rotate(float);
	virtual void Rotate(float, float, float);
	virtual void Update(float);
	virtual void Draw(int layer = 0, float alpha = -1.0f);
	virtual void SetColor(const float, const float, const float, const float);
	virtual void SetColor(const color clr);
};

class SpecialMeterWidget : public IGOWidget
{
private:
	static const color COLOR_NORMAL;
	static const color COLOR_SPECIAL;
	static const float SPEED_COLOR_FLASH;
	static const float FLASH_MIN;
	static const float FLASH_MAX;
	SpecialMeter *meter;
	PanelQuad *bgPQ;
	PanelQuad *colorPQ;
	PanelQuad *fgPQ;
	int flashDir;
	float flashAmt;
public:
	virtual void Draw(void);
};

__asm__(".equ Draw__9IGOWidget, 0x00164668");
__asm__(".equ CanRegionLink__C12SpecialMeter, 0x002510F0");
__asm__(".equ _18SpecialMeterWidget$COLOR_NORMAL, 0x003E7670");
__asm__(".equ _18SpecialMeterWidget$COLOR_SPECIAL, 0x003E7680");

void SpecialMeterWidget::Draw(void)
{
	color	meterColor;

	IGOWidget::Draw();

	if (!display)
		return;

	// Calculate meter's color.
	if (!meter->CanRegionLink())
		meterColor = COLOR_NORMAL;
	else
	{
		meterColor.r = COLOR_SPECIAL.r*flashAmt;
		meterColor.g = COLOR_SPECIAL.g*flashAmt;
		meterColor.b = COLOR_SPECIAL.b*flashAmt;
		meterColor.a = COLOR_SPECIAL.a;

		if (meterColor.r > 1.0f) meterColor.r = 1.0f;
		if (meterColor.g > 1.0f) meterColor.g = 1.0f;
		if (meterColor.b > 1.0f) meterColor.b = 1.0f;
	}

	// Set meter's color.
	colorPQ->SetColor(meterColor);

	// Draw components.
	bgPQ->Draw(0);
	colorPQ->Draw(0);
	fgPQ->Draw(0);
}
